 x.c['changed_fact']=T('Only hall availability changes: free east half A, fully booked hall with licensed porch fallback B.|仅会堂可用性变化：A东半空，B全订但有获准门廊备用。')
 return plans(x,a,bad,g1,wrong,g2)

